Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
$env:NPM_CONFIG_LOGLEVEL = "error"

$Root = (Get-Location).Path
$OwnerEmail = "viniciusadm@orcaly.com"
$OwnerName = "Vinícius Araújo"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path `
    $Root `
    ".orcaly-backups\owner-control-$Timestamp"
$TempRoot = Join-Path `
    $env:TEMP `
    "orcaly-owner-control-$Timestamp"
$ZipPath = Join-Path $TempRoot "payload.zip"
$ExtractRoot = Join-Path $TempRoot "payload"
$PackageFilesRoot = Join-Path $ExtractRoot "files"
$MigrationSource = Join-Path `
    $ExtractRoot `
    "database\owner_support_control.sql"
$PatcherSource = Join-Path `
    $ExtractRoot `
    "tools\internal-admin-patcher.mjs"
$BootstrapSource = Join-Path `
    $ExtractRoot `
    "tools\bootstrap-owner.mjs"
$BootstrapPath = Join-Path `
    $Root `
    ".orcaly-owner-bootstrap-$Timestamp.mjs"
$MigrationDirectory = Join-Path `
    $Root `
    "supabase\migrations"
$MigrationMarker = "ORCALY_OWNER_SUPPORT_CONTROL_V1"
$InstallerVersion = "V5_NULLABLE_FINANCIAL_SUMMARY"
$MigrationCreated = $false
$MigrationPath = ""
$PlainPassword = $null
$PasswordPointer = [IntPtr]::Zero

$PayloadBase64 = @'

'@

$TargetFiles = @(
    "lib/platform-admin.ts",
    "lib/admin-auth.ts",
    "app/api/admin/session/route.ts",
    "app/api/admin/audit/route.ts",
    "app/api/admin/team/route.ts",
    "app/api/admin/change-password/route.ts",
    "app/api/admin/affiliates/route.ts",
    "app/api/platform-admin/summary/route.ts",
    "app/admin/login/page.tsx",
    "app/admin/alterar-senha/page.tsx",
    "app/admin/equipe/page.tsx",
    "app/admin/auditoria/page.tsx",
    "app/admin/indicacoes/page.tsx",
    "components/admin/OwnerControlCenter.tsx",
    "components/admin/InternalAdminClient.tsx",
    "app/admin/page.tsx",
    "proxy.ts"
)

$CreatedDuringRun = New-Object `
    System.Collections.Generic.List[string]

function Write-Section([string]$Text) {
    Write-Host ""
    Write-Host ("=" * 76) -ForegroundColor DarkCyan
    Write-Host $Text -ForegroundColor Cyan
    Write-Host ("=" * 76) -ForegroundColor DarkCyan
}

function Write-Ok([string]$Text) {
    Write-Host "[OK] $Text" -ForegroundColor Green
}

function Write-Warn([string]$Text) {
    Write-Host "[AVISO] $Text" -ForegroundColor Yellow
}

function Native-Path([string]$Relative) {
    return Join-Path `
        $Root `
        ($Relative -replace "/", "\")
}

function Copy-WithParent(
    [string]$Source,
    [string]$Destination
) {
    $Parent = Split-Path -Parent $Destination

    if ($Parent) {
        New-Item `
            -ItemType Directory `
            -Path $Parent `
            -Force | Out-Null
    }

    Copy-Item `
        -LiteralPath $Source `
        -Destination $Destination `
        -Force
}

function Restore-Code {
    Write-Warn "Restaurando os arquivos anteriores..."

    foreach ($Relative in $TargetFiles) {
        $Backup = Join-Path `
            $BackupRoot `
            ($Relative -replace "/", "\")
        $Target = Native-Path $Relative

        if (Test-Path -LiteralPath $Backup) {
            Copy-WithParent `
                -Source $Backup `
                -Destination $Target
        }
        elseif (
            $CreatedDuringRun.Contains($Relative) -and
            (Test-Path -LiteralPath $Target)
        ) {
            Remove-Item `
                -LiteralPath $Target `
                -Force `
                -ErrorAction SilentlyContinue
        }
    }

    if (
        $MigrationCreated -and
        $MigrationPath -and
        (Test-Path -LiteralPath $MigrationPath)
    ) {
        Remove-Item `
            -LiteralPath $MigrationPath `
            -Force `
            -ErrorAction SilentlyContinue
    }
}

function Resolve-SupabaseCommand {
    $Command = Get-Command `
        supabase.exe `
        -ErrorAction SilentlyContinue

    if (-not $Command) {
        $Command = Get-Command `
            supabase `
            -ErrorAction SilentlyContinue
    }

    if ($Command) {
        return @{
            Command = $Command.Source
            Prefix = @()
        }
    }

    $Npx = Get-Command `
        npx.cmd `
        -ErrorAction SilentlyContinue

    if (-not $Npx) {
        $Npx = Get-Command `
            npx `
            -ErrorAction SilentlyContinue
    }

    if (-not $Npx) {
        throw "Supabase CLI e npx não foram encontrados."
    }

    return @{
        Command = $Npx.Source
        Prefix = @(
            "--yes",
            "supabase@latest"
        )
    }
}

function Find-OwnerMigration {
    if (-not (Test-Path -LiteralPath $MigrationDirectory)) {
        return @()
    }

    return @(
        Get-ChildItem `
            -LiteralPath $MigrationDirectory `
            -Filter "*.sql" `
            -File |
            Where-Object {
                $Content = Get-Content `
                    -LiteralPath $_.FullName `
                    -Raw `
                    -ErrorAction SilentlyContinue

                $Content -and
                $Content.Contains($MigrationMarker)
            }
    )
}

Write-Section "ORCALY - LOGIN DONO E CONTROLE GERAL - V5"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

git rev-parse --is-inside-work-tree | Out-Null

if ($LASTEXITCODE -ne 0) {
    throw "A pasta atual não é um repositório Git."
}

$AffiliateServer = Join-Path `
    $Root `
    "lib\affiliates\server.ts"
$AffiliatePanel = Join-Path `
    $Root `
    "app\parceiros\painel\page.tsx"

if (
    -not (Test-Path -LiteralPath $AffiliateServer) -or
    -not (Test-Path -LiteralPath $AffiliatePanel)
) {
    throw "O Programa de Parceiros V4 precisa estar instalado antes deste módulo."
}

$AffiliateContent = Get-Content `
    -LiteralPath $AffiliateServer `
    -Raw

if (-not $AffiliateContent.Contains("ORCALY_AFFILIATE_PROGRAM_V1")) {
    throw "O marcador do Programa de Parceiros não foi encontrado."
}

New-Item `
    -ItemType Directory `
    -Path $BackupRoot `
    -Force | Out-Null

foreach ($Relative in $TargetFiles) {
    $Target = Native-Path $Relative

    if (Test-Path -LiteralPath $Target) {
        $Backup = Join-Path `
            $BackupRoot `
            ($Relative -replace "/", "\")

        Copy-WithParent `
            -Source $Target `
            -Destination $Backup
    }
    else {
        $CreatedDuringRun.Add($Relative)
    }
}

Write-Ok "Backup criado: $BackupRoot"

try {
    Write-Section "EXTRAINDO O PACOTE"

    New-Item `
        -ItemType Directory `
        -Path $TempRoot `
        -Force | Out-Null

    [System.IO.File]::WriteAllBytes(
        $ZipPath,
        [Convert]::FromBase64String(
            ($PayloadBase64 -replace "\s", "")
        )
    )

    Expand-Archive `
        -LiteralPath $ZipPath `
        -DestinationPath $ExtractRoot `
        -Force

    Write-Ok "Pacote extraído"

    Write-Section "CRIANDO A MIGRAÇÃO LOCAL"

    New-Item `
        -ItemType Directory `
        -Path $MigrationDirectory `
        -Force | Out-Null

    $Migrations = @(Find-OwnerMigration)

    if ($Migrations.Count -gt 1) {
        throw "Mais de uma migration do controle do dono foi encontrada."
    }

    if ($Migrations.Count -eq 1) {
        $MigrationPath = $Migrations[0].FullName
        Write-Ok "Migration já existe: $MigrationPath"
    }
    else {
        $Supabase = Resolve-SupabaseCommand
        $Arguments = @()

        if ($Supabase.Prefix) {
            $Arguments += $Supabase.Prefix
        }

        $Arguments += @(
            "migration",
            "new",
            "owner_support_control_v1"
        )

        & $Supabase.Command @Arguments

        if ($LASTEXITCODE -ne 0) {
            throw "Não foi possível criar a migration local."
        }

        $CreatedMigration = Get-ChildItem `
            -LiteralPath $MigrationDirectory `
            -Filter "*_owner_support_control_v1.sql" `
            -File |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First 1

        if (-not $CreatedMigration) {
            throw "A migration recém-criada não foi localizada."
        }

        $MigrationPath = $CreatedMigration.FullName
        $MigrationCreated = $true

        Copy-Item `
            -LiteralPath $MigrationSource `
            -Destination $MigrationPath `
            -Force

        Write-Ok "Migration local: $MigrationPath"
    }

    Write-Host "A estrutura equivalente já foi aplicada no Supabase de produção." -ForegroundColor DarkCyan

    Write-Section "INSTALANDO O CENTRO DE CONTROLE"

    Get-ChildItem `
        -LiteralPath $PackageFilesRoot `
        -Recurse `
        -File |
        ForEach-Object {
            $Relative = $_.FullName.Substring(
                $PackageFilesRoot.Length + 1
            )
            $Destination = Join-Path `
                $Root `
                $Relative

            Copy-WithParent `
                -Source $_.FullName `
                -Destination $Destination

            Write-Ok ($Relative -replace "\\", "/")
        }

    Write-Section "ATUALIZANDO A NAVEGAÇÃO INTERNA"

    node $PatcherSource $Root

    if ($LASTEXITCODE -ne 0) {
        throw "O patch da navegação administrativa falhou."
    }

    Write-Section "VALIDANDO A IMPLEMENTAÇÃO"

    $Checks = @{
        "lib/platform-admin.ts" = @(
            "ORCALY_OWNER_SUPPORT_CONTROL_V1",
            "PlatformPermission",
            "team.manage",
            "pix.reveal",
            "payouts.send"
        )
        "lib/admin-auth.ts" = @(
            "ORCALY_OWNER_SUPPORT_CONTROL_V1",
            "export const supabaseAdmin = getSupabaseAdmin()",
            "requireAdmin",
            "auditLog"
        )
        "app/api/admin/affiliates/route.ts" = @(
            "review_referral",
            "reveal_pix",
            "list_affiliate_payout_accounts_admin",
            "const summary: Record<string, unknown>"
        )
        "app/api/admin/team/route.ts" = @(
            "create_support",
            "reset_password",
            "sanitizeSupportPermissions"
        )
        "app/admin/indicacoes/page.tsx" = @(
            "Controle geral de indicações",
            "Revisar indicação",
            "Revelar chave Pix",
            "Parceiros de destaque",
            "useMemo<Map<string, Json>>",
            "new Map<string, Json>"
        )
        "app/admin/equipe/page.tsx" = @(
            "Equipe administrativa",
            "Adicionar suporte",
            "Editar permissões"
        )
        "app/admin/auditoria/page.tsx" = @(
            "ORCALY_OWNER_SUPPORT_CONTROL_V1",
            "Auditoria administrativa",
            "Registros",
            "Eventos financeiros"
        )
        "proxy.ts" = @(
            "ORCALY_OWNER_SUPPORT_CONTROL_V1",
            "/admin/login",
            "orcaly_role"
        )
    }

    foreach ($Relative in $Checks.Keys) {
        $Target = Native-Path $Relative
        $Content = [System.IO.File]::ReadAllText(
            $Target,
            [System.Text.Encoding]::UTF8
        )

        foreach ($Marker in $Checks[$Relative]) {
            if (-not $Content.Contains($Marker)) {
                throw "Validação falhou em ${Relative}: $Marker"
            }
        }

        Write-Ok $Relative
    }

    $MigrationContent = [System.IO.File]::ReadAllText(
        $MigrationPath,
        [System.Text.Encoding]::UTF8
    )

    if (-not $MigrationContent.Contains($MigrationMarker)) {
        throw "O marcador da migration local está ausente."
    }

    Write-Section "VALIDANDO DIFF"

    git --no-pager diff --check

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    $Package = Get-Content `
        -LiteralPath (Join-Path $Root "package.json") `
        -Raw |
        ConvertFrom-Json

    if (
        $Package.scripts.PSObject.Properties.Name -contains
        "security:check"
    ) {
        Write-Section "VALIDANDO SEGURANÇA"

        npm run security:check

        if ($LASTEXITCODE -ne 0) {
            throw "security:check falhou."
        }

        Write-Ok "SECURITY_CHECK_EXIT_CODE=0"
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Section "EXECUTANDO BUILD COMPLETO"

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou. O login do dono ainda não foi alterado."
    }

    Write-Ok "BUILD_EXIT_CODE=0"

    Write-Section "CONFIGURANDO O LOGIN DONO"

    Write-Host "E-mail: $OwnerEmail"
    Write-Host "A senha será lida de forma oculta e não será gravada no script, banco ou Git." -ForegroundColor Cyan

    $SecurePassword = Read-Host `
        "Digite a senha que será usada pelo login DONO" `
        -AsSecureString

    $PasswordPointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR(
        $SecurePassword
    )

    $PlainPassword = [Runtime.InteropServices.Marshal]::PtrToStringBSTR(
        $PasswordPointer
    )

    if ([string]::IsNullOrWhiteSpace($PlainPassword)) {
        throw "A senha do dono não pode ficar vazia."
    }

    Copy-Item `
        -LiteralPath $BootstrapSource `
        -Destination $BootstrapPath `
        -Force

    $env:ORCALY_OWNER_EMAIL = $OwnerEmail
    $env:ORCALY_OWNER_NAME = $OwnerName
    $env:ORCALY_OWNER_PASSWORD = $PlainPassword

    try {
        node $BootstrapPath

        if ($LASTEXITCODE -ne 0) {
            throw "Não foi possível criar ou atualizar o login do dono."
        }
    }
    finally {
        Remove-Item `
            Env:\ORCALY_OWNER_PASSWORD `
            -ErrorAction SilentlyContinue
        Remove-Item `
            Env:\ORCALY_OWNER_EMAIL `
            -ErrorAction SilentlyContinue
        Remove-Item `
            Env:\ORCALY_OWNER_NAME `
            -ErrorAction SilentlyContinue

        $PlainPassword = $null

        if ($PasswordPointer -ne [IntPtr]::Zero) {
            [Runtime.InteropServices.Marshal]::ZeroFreeBSTR(
                $PasswordPointer
            )
            $PasswordPointer = [IntPtr]::Zero
        }

        Remove-Item `
            -LiteralPath $BootstrapPath `
            -Force `
            -ErrorAction SilentlyContinue
    }

    Write-Section "LOGIN DONO E PAINEL CONFIGURADOS"

    Write-Host "Login administrativo: /admin/login"
    Write-Host "E-mail do dono: $OwnerEmail"
    Write-Host "Dashboard geral: /admin"
    Write-Host "Controle de parceiros: /admin/indicacoes"
    Write-Host "Equipe de suporte: /admin/equipe"
    Write-Host "Auditoria: /admin/auditoria"
    Write-Host "Senha armazenada pelo sistema: NÃO"
    Write-Host "Chave Pix completa: somente DONO"
    Write-Host "Envio e confirmação de Pix: somente DONO"
    Write-Host "Criação de suporte: somente DONO"
    Write-Host "Revisão de indicações: conforme permissão"
    Write-Host "Build: aprovado"
    Write-Host "Commit: não realizado"
    Write-Host "Deploy: não realizado"
    Write-Host ""
    Write-Host "O login de dono anterior foi preservado como acesso de recuperação." -ForegroundColor Cyan
}
catch {
    Restore-Code
    throw
}
finally {
    Remove-Item `
        Env:\ORCALY_OWNER_PASSWORD `
        -ErrorAction SilentlyContinue
    Remove-Item `
        Env:\ORCALY_OWNER_EMAIL `
        -ErrorAction SilentlyContinue
    Remove-Item `
        Env:\ORCALY_OWNER_NAME `
        -ErrorAction SilentlyContinue

    $PlainPassword = $null

    if ($PasswordPointer -ne [IntPtr]::Zero) {
        [Runtime.InteropServices.Marshal]::ZeroFreeBSTR(
            $PasswordPointer
        )
    }

    Remove-Item `
        -LiteralPath $BootstrapPath `
        -Force `
        -ErrorAction SilentlyContinue

    Remove-Item `
        -LiteralPath $TempRoot `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue
}
